const S={screens:[],runs:[],decisions:[],catalog:[],companies:[],companySelection:new Set(),defaultDataset:null,contextToken:0,revision:null,run:null,resultContent:null,preview:null,busy:false,selected:new Set(),activeFilter:"ALL",dirty:false,lastFocus:null,evidenceRow:null,admin:new URLSearchParams(location.search).get("mode")==="admin",explorerDataset:null,explorerYear:null,explorer:null,library:null,explorerCatalog:null,explorerCatalogKey:null,explorerCatalogToken:0,explorerSelected:new Set(),profile:null,profileMetric:"revenue",view:"explorer",explorerToken:0,libraryToken:0,frequencyDrafts:{},quarterSpine:[],frequency:"ANNUAL"};const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
async function api(path,options={}){const r=await fetch(path,{headers:{"Content-Type":"application/json"},...options}),b=await r.json().catch(()=>({error:`요청 오류 ${r.status}`}));if(!r.ok)throw new Error(b.error||"요청에 실패했습니다.");return b}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(m){const e=$("#toast");e.textContent=m;e.classList.add("visible");setTimeout(()=>e.classList.remove("visible"),1800)}
function fail(e){const m=e.message||String(e);$("#criteria-error").hidden=false;$("#criteria-error").textContent=m.startsWith("metric is unavailable for execution:")?"현재 자료에서 실행할 수 없는 지표가 포함돼 있습니다. 사용 가능한 지표를 선택해 주세요.":m}
function categoryLabel(v){return ({GROWTH:"성장성",PROFITABILITY:"수익성",CASH_FLOW:"현금흐름",FINANCIAL_STABILITY:"재무안정성",OTHER_REPORTED:"공시항목"})[v]||v}
function aggregateLabel(v){return ({PASS:"조건 충족",FAIL:"조건 미충족",UNDETERMINED:"자료 확인 필요"})[v]||v}
function decisionLabel(v){return ({INTEREST:"관심",HOLD:"보류",EXCLUDE:"제외"})[v]||v||"기록 없음"}
function metricById(id){return S.catalog.find(x=>x.metric_id===id)||{metric_id:id,label:id,category:"OTHER_REPORTED",unit_kind:"MONEY",unit:"USD",definition_version:"annual-core-reported-v1",period_class:"FY",coverage:{}}}
// Display only: exact decimal half-up rounding, with ties away from zero.
function formatDecimal(v,places=1){
  if(v===null||v===undefined)return"—";
  const normalized=shiftDecimal(String(v),0),negative=normalized.startsWith("-"),absolute=negative?normalized.slice(1):normalized;
  const [whole,fraction=""]=absolute.split("."),kept=fraction.padEnd(places,"0").slice(0,places);
  let scaled=BigInt(whole+kept);
  if((fraction[places]||"0")>="5")scaled+=1n;
  const digits=scaled.toString().padStart(places+1,"0"),integer=places?digits.slice(0,-places):digits;
  return(negative&&scaled!==0n?"-":"")+integer.replace(/\B(?=(\d{3})+(?!\d))/g,",")+(places?"."+digits.slice(-places):"");
}
function shiftDecimal(v,p){const c=String(v).trim().replace(/,/g,""),m=c.match(/^([+-]?)(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$/);if(!m||(m[2]+m[3]).length===0)throw new Error("숫자 형식을 확인해 주세요.");const s=m[1]==="-"?"-":"",w=m[2]||"",f=m[3]||"",raw=w+f;if(/^0+$/.test(raw))return"0";const leading=(raw.match(/^0*/)||[""])[0].length,d=raw.slice(leading),q=w.length+Number(m[4]||0)+p-leading;let o=q<=0?"0."+"0".repeat(-q)+d:q>=d.length?d+"0".repeat(q-d.length):d.slice(0,q)+"."+d.slice(q);o=o.replace(/^0+(?=\d)/,"");if(o.includes("."))o=o.replace(/0+$/,"").replace(/\.$/,"");o=o||"0";return o==="0"?o:s+o}
function displayValue(v,m){return v===null||v===undefined?"—":m.unit_kind==="MONEY"?formatDecimal(shiftDecimal(v,-6),1):formatDecimal(v,2)}
function numberMarkup(v,m){const text=displayValue(v,m);return`<span class="display-number explorer-value" title="${esc(v)} ${esc(m.unit||unitLabel(m))}" aria-label="${esc(text)} ${esc(unitLabel(m))}"><span class="number-text">${esc(text)}</span><span class="number-clipped" aria-hidden="true">…</span></span>`}
function thresholdToApi(v,m){return shiftDecimal(v,m.unit_kind==="MONEY"?6:0)}
function thresholdFromApi(v,m){return shiftDecimal(v,m.unit_kind==="MONEY"?-6:0)}
function unitLabel(m){return m.unit_kind==="MONEY"?"백만 달러":"%"}
function businessReason(c){return ({MULTIPLE_CANDIDATES:"같은 기간의 값이 여러 개입니다.",PERIOD_NOT_PREPARED:"선택한 기간의 자료가 없습니다.",MISSING_INPUT:"계산에 필요한 공시 항목이 없습니다.",QUALITY_BLOCKED:"자료 품질 확인이 필요합니다.",MAPPING_REVIEW_REQUIRED:"공시 항목 확인이 필요합니다.",NON_POSITIVE_DENOMINATOR:"비율 계산 기준값을 사용할 수 없습니다.",NEGATIVE_EQUITY:"자본이 음수여서 비율을 제공하지 않습니다.",CAPEX_SIGN_UNCERTAIN:"투자지출 표시 방향을 확인해야 합니다.",UNSUPPORTED_FISCAL_QUARTER_DURATION:"일반적인 3개월 분기보다 기간이 길어 비교에서 보류했습니다.",INPUTS_NOT_COMPATIBLE:"연속 분기의 계산 기준이 달라 값을 제공하지 않습니다.",NO_FILING_AS_OF_CUTOFF:"기준일까지 해당 분기 공시가 없습니다."})[c]||"공시자료 확인이 필요합니다."}
function filteredCatalog(){const c=$("#metric-category").value,n=$("#metric-search").value.trim().toLowerCase();return S.catalog.filter(x=>(!c||x.category===c)&&(!n||x.label.toLowerCase().includes(n)||x.metric_id.toLowerCase().includes(n)))}
function metricOptions(selected){let rows=filteredCatalog();const keep=metricById(selected);if(selected&&!rows.some(x=>x.metric_id===selected))rows=[keep,...rows];return ["GROWTH","PROFITABILITY","CASH_FLOW","FINANCIAL_STABILITY","OTHER_REPORTED"].map(c=>{const a=rows.filter(x=>x.category===c);return a.length?`<optgroup label="${categoryLabel(c)}">${a.map(x=>{const v=x.coverage||{},coverage=v.companies_total?` · ${v.companies_available}/${v.companies_total}개 기업`:"",disabled=x.business_availability==="UNAVAILABLE"&&x.metric_id!==selected;return`<option value="${esc(x.metric_id)}" ${x.metric_id===selected?'selected':''} ${disabled?'disabled':''}>${esc(x.label)} · ${unitLabel(x)}${coverage}${disabled?' · 현재 사용 불가':''}</option>`}).join("")}</optgroup>`:""}).join("")}
function predicateRow(v){const m=metricById(v?.metric_id||filteredCatalog()[0]?.metric_id||S.catalog[0]?.metric_id||"revenue"),r=document.createElement("div");r.className="predicate";r.innerHTML=`<label>지표<select class="metric">${metricOptions(m.metric_id)}</select><span class="metric-hint"></span></label><label>조건<select class="operator"><option value="GTE">이상</option><option value="GT">초과</option><option value="LTE">이하</option><option value="LT">미만</option><option value="EQ">같음</option></select></label><label><span class="field-caption">기준값 (<span class="threshold-unit"></span>)</span><input class="threshold" inputmode="decimal" required></label><button type="button" class="quiet remove">삭제</button>`;r.querySelector(".operator").value=v?.operator||"GTE";r.querySelector(".threshold").value=v?thresholdFromApi(v.threshold,m):"0";updatePredicateHint(r);r.querySelector(".metric").onchange=()=>{updatePredicateHint(r);markDirty()};r.querySelector(".remove").onclick=()=>{if($$(".predicate").length>1){r.remove();markDirty()}};$("#predicates").append(r)}
function updatePredicateHint(r){const m=metricById(r.querySelector(".metric").value),c=m.coverage||{},basis=m.observation_basis||m.period_class,basisLabel=({INSTANT:"기말잔액",QTD_3M:"분기실적",TTM:"최근4분기"})[basis]||"연간실적";r.querySelector(".threshold-unit").textContent=unitLabel(m);r.querySelector(".metric-hint").innerHTML=`${categoryLabel(m.category)} · ${basisLabel} <span class="coverage">${c.companies_available??c.available_companies??"—"}개 기업 사용 가능</span>`}
function refreshMetricOptions(){$$(".predicate").forEach(r=>{const s=r.querySelector(".metric"),v=s.value;s.innerHTML=metricOptions(v);if([...s.options].some(x=>x.value===v))s.value=v;updatePredicateHint(r)})}
function revisionContent(){const mode=$("#universe-mode").value;let universe={mode:"ALL_PREPARED"};if(mode==="CIKS")universe={mode,ciks:[...S.companySelection]};if(mode==="SIC")universe={mode,sic_codes:[$("#industry-select").value]};const period=$("#frequency").value==="QUARTERLY"?{mode:"FIXED_CALENDAR_QUARTER_END",calendar_year:Number($("#calendar-quarter").value.slice(0,4)),calendar_quarter:Number($("#calendar-quarter").value.slice(-1))}:$("#period-mode").value==="FIXED_FISCAL_YEAR"?{mode:"FIXED_FISCAL_YEAR",fiscal_year:Number($("#fiscal-year").value)}:{mode:"LATEST_COMPLETE_ANNUAL",offset:Number($("#period-offset").value)};return{universe,predicates:$$(".predicate").map(r=>{const m=metricById(r.querySelector(".metric").value);return{metric_id:m.metric_id,operator:r.querySelector(".operator").value,threshold:thresholdToApi(r.querySelector(".threshold").value,m),definition_version:m.definition_version}}),period_policy:period,columns:$$('[name="visible-column"]:checked').map(x=>x.value),sort:{column:$("#sort-column").value,direction:$("#sort-direction").value}}}
function markDirty(){S.dirty=true;S.preview=null;$("#save-result").disabled=true;$("#save-state").textContent=S.revision?"수정됨 · 저장 필요":"저장 전 · 저장 필요"}
function isRevisionEdit(t){return t instanceof Element&&!t.closest("#saved-screen,#open-screen,#dataset,#metric-category,#metric-search,#company-query")}
function setCriteriaCompact(c){$(".criteria").classList.toggle("compact",c);$("#toggle-criteria").setAttribute("aria-expanded",String(!c));$("#toggle-criteria").textContent=c?"조건 펼치기":"조건 접기"}

async function refreshScreens(){S.screens=await api("/api/screen-revisions");$("#saved-screen").innerHTML='<option value="">새 조건</option>'+S.screens.map(x=>`<option value="${x.revision_id}">${esc(x.name)} · v${x.revision_number}</option>`).join("");renderTimeline()}
async function refreshRuns(){S.runs=await api("/api/runs");const o='<option value="">실행 선택</option>'+S.runs.map(x=>`<option value="${x.run_id}">${esc(x.result_name||S.screens.find(s=>s.revision_id===x.revision_id)?.name||"저장 결과")} · ${esc(x.created_at?.slice(0,16)||"")} · 대상 ${x.counts.target}</option>`).join("");$("#old-run").innerHTML=o;$("#new-run").innerHTML=o;renderTimeline()}
async function saveScreen(){const c=revisionContent();if(!c.predicates.length)throw new Error("재무 조건을 하나 이상 추가해 주세요.");if(!c.columns.length)throw new Error("표시 항목을 하나 이상 선택해 주세요.");$("#save-state").textContent="저장 중…";const r=S.revision?await api(`/api/screens/${S.revision.screen_id}/revisions`,{method:"POST",body:JSON.stringify({content:c,dataset_id:$("#dataset").value})}):await api("/api/screens",{method:"POST",body:JSON.stringify({name:$("#screen-name").value,content:c,dataset_id:$("#dataset").value})});S.revision=r;S.dirty=false;$("#screen-name").readOnly=true;$("#save-state").textContent=`저장됨 · v${r.revision_number}`;$("#screen-context").textContent=`${$("#screen-name").value} · v${r.revision_number}`;await refreshScreens();$("#saved-screen").value=r.revision_id;toast("조건을 저장했습니다.")}
function columnEnabled(c,g){const a={company:["company","ticker","name","cik"],aggregate:["aggregate"],predicates:["predicates"],decision:["decision"]};return(a[g]||[g]).some(x=>c.includes(x))}
function loadScreenRecord(s){if(!s)return;S.revision=s;S.dirty=false;$("#screen-name").value=s.name;$("#screen-name").readOnly=true;const c=s.content;$("#universe-mode").value=c.universe.mode;toggleUniverse();S.companySelection=new Set(c.universe.mode==="CIKS"?(c.universe.ciks||[]):[]);renderCompanyOptions();if(c.universe.mode==="SIC")$("#industry-select").value=(c.universe.sic_codes||[])[0]||"";const quarterly=c.period_policy.mode==="FIXED_CALENDAR_QUARTER_END";$("#frequency").value=quarterly?"QUARTERLY":"ANNUAL";S.frequency=quarterly?"QUARTERLY":"ANNUAL";if(quarterly)$("#calendar-quarter").value=`${c.period_policy.calendar_year}Q${c.period_policy.calendar_quarter}`;else $("#period-mode").value=c.period_policy.mode;togglePeriod();if(c.period_policy.fiscal_year)$("#fiscal-year").value=c.period_policy.fiscal_year;$("#period-offset").value=c.period_policy.offset||0;$("#predicates").innerHTML="";c.predicates.forEach(predicateRow);const sort=$("#sort-column");if(![...sort.options].some(x=>x.value===c.sort.column)){const o=document.createElement("option");o.value=c.sort.column;o.textContent="저장된 정렬";sort.append(o)}sort.value=c.sort.column;$("#sort-direction").value=c.sort.direction;$$('[name="visible-column"]').forEach(x=>x.checked=columnEnabled(c.columns,x.value));$("#screen-context").textContent=`${s.name} · v${s.revision_number}`;$("#save-state").textContent="저장된 조건"}
function toggleUniverse(){const m=$("#universe-mode").value;$("#company-select-label").hidden=m!=="CIKS";$("#industry-select-label").hidden=m!=="SIC"}
function togglePeriod(){const q=$("#frequency").value==="QUARTERLY",f=$("#period-mode").value==="FIXED_FISCAL_YEAR";$("#period-mode").closest("label").hidden=q;$("#calendar-quarter-label").hidden=!q;$("#fiscal-year-label").hidden=q||!f;$("#offset-label").hidden=q||f}
function quarterLabel(x){const months=({1:"1–3월",2:"4–6월",3:"7–9월",4:"10–12월"})[x.calendar_quarter];return`${x.calendar_year}년 ${months}에 종료한 분기`}
async function switchFrequency(){clearResult();const target=$("#frequency").value==="QUARTERLY"?"QUARTERLY":"ANNUAL",q=target==="QUARTERLY",draft=S.frequencyDrafts[target],d=q?S.defaultDataset:(draft?.dataset||S.defaultDataset);$("#dataset").value=d.dataset_id;$("#asof").textContent=d.financial_as_of;await loadCompanies(d.dataset_id,++S.contextToken);if(q){const [catalog,periods]=await Promise.all([api(`/api/quarter-metric-catalog?dataset_id=${encodeURIComponent(d.dataset_id)}`),api(`/api/quarter-periods?dataset_id=${encodeURIComponent(d.dataset_id)}`)]);S.catalog=catalog;S.quarterSpine=periods.spine;$("#calendar-quarter").innerHTML=periods.spine.map(x=>`<option value="${x.calendar_year}Q${x.calendar_quarter}">${quarterLabel(x)}</option>`).join("");$("#calendar-quarter").value=`${periods.spine.at(-1).calendar_year}Q${periods.spine.at(-1).calendar_quarter}`}else await loadCatalog(d.dataset_id,S.contextToken);if(draft){loadScreenRecord({name:draft.name,content:draft.content,revision_number:draft.revision?.revision_number||"저장 전"});S.revision=draft.revision;S.dirty=draft.dirty;$("#saved-screen").value=draft.revision?.revision_id||"";$("#screen-name").readOnly=Boolean(draft.revision);$("#save-state").textContent=draft.dirty?"수정됨 · 저장 필요":draft.revision?"저장된 조건":"저장 전 · 저장 필요"}else{$("#frequency").value=target;$("#predicates").innerHTML="";predicateRow();S.revision=null;S.dirty=true;$("#saved-screen").value="";$("#screen-name").readOnly=false;$("#screen-name").value="";$("#screen-context").textContent="새 조건 · 저장 전";$("#save-state").textContent="저장 전 · 저장 필요"}S.frequency=target;togglePeriod()}

async function execute(){const content=revisionContent();clearResult();$("#result-body").innerHTML='<tr><td colspan="5" class="empty">기업을 찾는 중…</td></tr>';const r=await api("/api/preview",{method:"POST",body:JSON.stringify({content,dataset_id:$("#dataset").value})});S.preview=r;setRun(r,content);toast("시험 실행입니다. 필요한 결과만 저장하세요.")}
async function saveResult(){const p=S.preview;if(!p)throw new Error("조건을 시험 실행한 뒤 결과를 저장해 주세요.");const name=$("#screen-name").value.trim()||"스크리닝 결과",sameRevision=S.revision?.content_hash===p.condition_hash&&(!S.revision.saved_context||S.revision.saved_context.dataset_id===p.dataset_id);const r=await api("/api/results",{method:"POST",body:JSON.stringify({name,content:p.content,dataset_id:p.dataset_id,preview_hash:p.preview_hash,revision_id:sameRevision?S.revision.revision_id:null})});S.preview=null;setRun(r,p.content);await refreshRuns();toast("결과를 저장했습니다. 이력에서 다시 열 수 있습니다.")}
function syncResultActions(){const saved=Boolean(S.run?.run_id);$("#save-result").disabled=S.busy||!S.preview;["#export-selected-csv","#export-selected-xlsx","#export-full-csv","#export-full-xlsx","#save-decision"].forEach(id=>$(id).disabled=S.busy||!saved)}
async function withBusy(action){if(S.busy)return;S.busy=true;$("#criteria-error").hidden=true;const controls=$$("#criteria-form input,#criteria-form select,#criteria-form button,.criteria .button-row button,#open-run,#compare-runs,#result-body button.company,[data-guide-add]");const before=controls.map(x=>[x,x.disabled]);controls.forEach(x=>x.disabled=true);syncResultActions();try{return await action()}finally{S.busy=false;before.forEach(([x,disabled])=>{if(x.isConnected)x.disabled=disabled});syncResultActions()}}
function clearResult(){S.run=null;S.preview=null;S.resultContent=null;S.selected.clear();$("#result-body").innerHTML='<tr><td colspan="5" class="empty">조건을 시험 실행하면 결과가 표시됩니다.</td></tr>';$("#counts").textContent="실행 전";$("#evidence").hidden=true;syncResultActions()}
function setRun(r,content){S.run=r;S.resultContent=content||S.revision?.content;S.selected.clear();$("#period-context").textContent=r.period_policy.mode==="FIXED_FISCAL_YEAR"?`FY${r.period_policy.fiscal_year}`:r.period_policy.mode==="FIXED_CALENDAR_QUARTER_END"?quarterLabel(r.period_policy):`최근 완료 연도${r.period_policy.offset?` -${r.period_policy.offset}`:""}`;$("#asof").textContent=r.financial_as_of;$("#counts").textContent=`${r.run_id?"저장된 결과":"시험 결과 · 저장 전"} · 대상 ${r.counts.target} · 충족 ${r.counts.pass} · 미충족 ${r.counts.fail} · 확인 필요 ${r.counts.undetermined}`;renderRows();syncResultActions();setCriteriaCompact(true)}
function selectedMetrics(){return(S.resultContent?.predicates||[]).map(x=>metricById(x.metric_id))}
function decisionFor(cik){const e=S.decisions.filter(x=>x.cik===cik);return e.length?`<span class="badge review">${decisionLabel(e.at(-1).state)}</span>`:'<span class="muted">기록 없음</span>'}
function renderRows(){if(!S.run)return;const ms=selectedMetrics(),showCompany=!S.admin||columnEnabled(S.resultContent.columns,"company");$("#result-head").innerHTML=`<tr><th><span class="sr-only">선택</span></th><th ${showCompany?'':'hidden'}>기업</th><th>결과</th>${ms.map(m=>`<th>${esc(m.label)}<br><small>${unitLabel(m)}</small></th>`).join("")}<th>관심상태</th></tr>`;const rows=S.run.rows.filter(r=>S.activeFilter==="ALL"||r.aggregate===S.activeFilter).filter(r=>$("#show-all").checked||r.aggregate==="PASS");$("#result-body").innerHTML=rows.length?rows.map(row=>`<tr data-cik="${row.cik}" class="${S.selected.has(row.cik)?'selected':''}"><td><input type="checkbox" aria-label="${esc(row.ticker)} 선택" ${S.selected.has(row.cik)?'checked':''}></td><td ${showCompany?'':'hidden'}><button class="company" data-open="${row.cik}"><strong>${esc(row.name||row.ticker)}</strong><small>${esc(row.ticker)}</small></button></td><td><span class="badge ${row.aggregate.toLowerCase()}">${aggregateLabel(row.aggregate)}</span></td>${row.predicates.map(p=>{const m=metricById(p.metric_id),o=p.observation||{},missing=o.value===null||o.value===undefined;return`<td class="metric-cell" title="${missing?esc(businessReason(p.reason)):esc(m.label+' · '+(o.period_end||o.context_end_date||''))}">${missing?'—':numberMarkup(o.value,m)}${missing?'<small>자료 확인 필요</small>':''}</td>`}).join("")}<td>${decisionFor(row.cik)}</td></tr>`).join(""):`<tr><td colspan="${4+ms.length}" class="empty">해당하는 기업이 없습니다.</td></tr>`;$$('[data-cik] input').forEach(x=>x.onchange=()=>{const c=x.closest("tr").dataset.cik;x.checked?S.selected.add(c):S.selected.delete(c);renderRows()});$$('[data-open]').forEach(x=>x.onclick=()=>withBusy(()=>openEvidence(x.dataset.open,x)).catch(fail))}

async function openEvidence(cik,b){S.lastFocus=b;S.evidenceRow=S.run.rows.find(x=>x.cik===cik);const r=S.evidenceRow;$("#evidence-title").textContent=`${r.name||r.ticker} 재무 상세`;$("#evidence-metric").innerHTML=r.predicates.map(x=>`<option value="${x.metric_id}">${esc(metricById(x.metric_id).label)}</option>`).join("");const p=await api(`/api/peers?dataset_id=${encodeURIComponent(S.run.dataset_id)}&dataset_publication_id=${encodeURIComponent(S.run.dataset_publication_id)}&cik=${cik}`);$("#peer-company").innerHTML='<option value="">기업 선택</option>'+p.peers.filter(x=>x.financial_prepared).map(x=>`<option value="${x.cik}">${esc((x.tickers||[])[0]||x.name)}</option>`).join("");$("#peer-comparison").textContent="같은 업종의 넓은 후보군이며 재무항목이 같다는 뜻은 아닙니다.";$("#evidence").dataset.cik=cik;$("#evidence").hidden=false;await renderMetricEvidence();$("#evidence").focus()}
function metricHelp(m){return m.description||({revenue_yoy:"올해 매출과 직전 회계연도 매출을 비교한 성장률입니다.",gross_margin:"매출총이익을 매출로 나눈 비율입니다.",operating_margin:"영업이익을 매출로 나눈 비율입니다.",net_margin:"순이익을 매출로 나눈 비율입니다.",standardized_fcf:"영업활동 현금흐름에서 유형자산 취득 지출을 뺀 표준화 지표입니다. 회사가 별도로 제시하는 FCF와 같다는 뜻은 아닙니다.",fcf_margin:"표준화 FCF를 매출로 나눈 비율입니다.",current_ratio:"유동자산을 유동부채로 나눈 기말 비율입니다.",liabilities_to_equity:"부채총계를 자본으로 나눈 비율입니다. 부채총계는 차입금과 다릅니다.",liabilities_to_assets:"부채총계를 자산으로 나눈 비율입니다.",net_debt:"직접 보고된 결합 차입금에서 현금 및 현금성자산을 뺀 금액입니다."})[m.metric_id]||"회사가 보고한 공시 항목입니다."}
function quarterSourceLabel(v){return({REPORTED:"보고값",DERIVED_QUARTER:"승인된 분기 계산",DERIVED_METRIC:"승인된 파생지표",UNAVAILABLE:"자료 확인 필요"})[v]||"자료 확인 필요"}
function actualPeriod(x){const end=x.period_end?inclusiveEnd(x.period_end):x.context_end_date;return x.period_start?`${x.period_start} ~ ${end||"—"}`:end||"—"}
function fiscalLabel(x){return x.fiscal_year&&x.fiscal_quarter?`FY${x.fiscal_year} ${x.fiscal_quarter}`:"—"}
async function renderMetricEvidence(){const id=$("#evidence-metric").value,m=metricById(id),r=S.evidenceRow,e=r.predicates.find(x=>x.metric_id===id),o=e.observation||{},quarterly=S.run.period_policy?.mode==="FIXED_CALENDAR_QUARTER_END",seriesPath=quarterly?`/api/quarter-series?dataset_id=${encodeURIComponent(S.run.dataset_id)}&dataset_publication_id=${encodeURIComponent(S.run.dataset_publication_id)}&cik=${r.cik}&metric_id=${encodeURIComponent(id)}&limit=8`:`/api/series?dataset_id=${encodeURIComponent(S.run.dataset_id)}&dataset_publication_id=${encodeURIComponent(S.run.dataset_publication_id)}&cik=${r.cik}&metric_id=${encodeURIComponent(id)}`;const [series,trace]=await Promise.all([api(seriesPath),S.run.run_id?api(`/api/runs/${encodeURIComponent(S.run.run_id)}/trace?cik=${r.cik}&metric_id=${encodeURIComponent(id)}`):Promise.resolve({evaluation:e})]),source=trace.evaluation?.observation||o,filings=source.source_filings||[],inputs=(m.input_metric_ids||[]).map(x=>metricById(x).label),basis=quarterly?(m.observation_basis==="INSTANT"?"기말잔액":m.observation_basis==="TTM"?"최근 4개 분기":"3개월 분기 실적"):(m.period_class==="INSTANT"?"회계연도 말의 기말잔액":"해당 회계연도의 연간실적");$("#evidence-content").innerHTML=`<div class="financial-summary"><div><span>${esc(m.label)}</span><strong>${o.value===null||o.value===undefined?'—':numberMarkup(o.value,m)} ${unitLabel(m)}</strong></div><div><span>자료 기간</span><strong>${esc(actualPeriod(o))}</strong></div></div><p>${esc(metricHelp(m))}</p>${inputs.length?`<p class="muted">계산 입력: ${inputs.map(esc).join(", ")}</p>`:""}<p>${esc(basis)}${quarterly?` · ${esc(quarterSourceLabel(o.source_kind))} · ${esc(fiscalLabel(o))}`:""}</p>${filings.length?`<p class="muted">관련 공시 ${filings.map(esc).join(", ")}</p>`:""}${o.value===null||o.value===undefined?`<p class="message error">${esc(businessReason(e.reason))}</p>`:""}`;$("#series-content").innerHTML=`<table class="series-table"><thead><tr><th>${quarterly?"종료 분기 · 회사 회계표시":"연도"}</th><th>실제 기간</th><th>${esc(m.label)} (${unitLabel(m)})</th>${quarterly?"<th>자료 성격</th>":""}</tr></thead><tbody>${series.observations.map(x=>`<tr><td>${quarterly?`${esc(quarterLabel(x))}<small>${esc(fiscalLabel(x))}</small>`:x.fiscal_year}</td><td>${esc(actualPeriod(x))}</td><td>${x.value===null||x.value===undefined?`<span title="${esc(businessReason(x.reason))}">—</span>`:numberMarkup(x.value,m)}</td>${quarterly?`<td>${esc(quarterSourceLabel(x.source_kind))}</td>`:""}</tr>`).join("")}</tbody></table>`}
async function comparePeer(){const peer=$("#peer-company").value;if(!peer)throw new Error("비교 기업을 선택해 주세요.");const id=$("#evidence-metric").value,m=metricById(id),quarterly=S.run.period_policy?.mode==="FIXED_CALENDAR_QUARTER_END";let path;if(quarterly){const p=S.run.period_policy;path=`/api/quarter-comparison?dataset_id=${encodeURIComponent(S.run.dataset_id)}&dataset_publication_id=${encodeURIComponent(S.run.dataset_publication_id)}&ciks=${S.evidenceRow.cik},${peer}&metric_id=${encodeURIComponent(id)}&calendar_year=${p.calendar_year}&calendar_quarter=${p.calendar_quarter}`}else{const e=S.evidenceRow.predicates.find(x=>x.metric_id===id),year=e.observation?.fiscal_year;if(!year)throw new Error("비교할 기간 자료가 없습니다.");path=`/api/peer-comparison?dataset_id=${encodeURIComponent(S.run.dataset_id)}&dataset_publication_id=${encodeURIComponent(S.run.dataset_publication_id)}&ciks=${S.evidenceRow.cik},${peer}&metric_id=${encodeURIComponent(id)}&fiscal_year=${year}`}const r=await api(path);$("#peer-comparison").innerHTML=`${r.warning?`<p>${esc(r.warning)}</p>`:""}<table class="series-table"><thead><tr><th>기업</th><th>${quarterly?"회사 회계표시":"기간"}</th><th>실제 기간</th><th>${esc(m.label)} (${unitLabel(m)})</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${esc(x.company.ticker)}</td><td>${quarterly?esc(fiscalLabel(x.observation||{})):esc(x.observation?.fiscal_year||"—")}</td><td>${esc(actualPeriod(x.observation||{}))}</td><td>${x.observation?.value===null||x.observation?.value===undefined?'—':numberMarkup(x.observation.value,m)}</td></tr>`).join("")}</tbody></table>`}
async function saveDecision(){if(!S.run?.run_id)throw new Error("결과를 저장한 뒤 관심상태를 기록해 주세요.");const cik=$("#evidence").dataset.cik,r=$("#decision-rationale").value.trim();if(!r)throw new Error("판단 메모를 입력해 주세요.");await api("/api/decisions",{method:"POST",body:JSON.stringify({cik,state:$("#decision-state").value,rationale:r,run_id:S.run.run_id,actor:"local-user",evidence_ids:[S.run.run_id]})});S.decisions=await api("/api/decisions");renderRows();renderTimeline();toast("관심상태를 기록했습니다.")}
function renderTimeline(){const a=[...S.screens.map(x=>({k:"조건 저장",t:`${x.name} v${x.revision_number}`,d:x.created_at})),...S.runs.map(x=>({k:"결과 저장",t:`${x.result_name||"저장 결과"} · 대상 ${x.counts.target} · 충족 ${x.counts.pass} · 확인 필요 ${x.counts.undetermined}`,d:x.created_at})),...S.decisions.map(x=>({k:"관심상태",t:`${decisionLabel(x.before_state)} → ${decisionLabel(x.state)} · ${x.rationale}`,d:x.created_at,c:"decision"}))];$("#timeline").innerHTML=a.map(x=>`<li class="${x.c||''}"><b>${x.k}</b> · ${esc(x.t)} <time>${esc(x.d||"")}</time></li>`).join("")||'<li>아직 이력이 없습니다.</li>'}
async function openRun(id){if(!id)throw new Error("결과를 선택해 주세요.");const r=await api(`/api/runs/${id}`),v=await api(`/api/revisions/${r.revision_id}`);await openSavedScreenRecord(v,r.dataset_id);S.revision=S.screens.find(x=>x.revision_id===v.revision_id)||null;$("#screen-name").readOnly=Boolean(S.revision);$("#saved-screen").value=S.revision?.revision_id||"";S.preview=null;setRun(r,v.content);showView("screening",true)}
async function compareRuns(){const a=$("#old-run").value,b=$("#new-run").value;if(!a||!b)throw new Error("두 실행을 선택해 주세요.");const d=await api(`/api/run-comparison?old_run_id=${encodeURIComponent(a)}&new_run_id=${encodeURIComponent(b)}`);$("#run-diff").textContent=d.differences.length?`${d.differences.length}개 기업의 결과 또는 값이 달라졌습니다.`:"기업 결과는 동일합니다."}
async function exportRun(scope,format){if(!S.run?.run_id)throw new Error("결과를 저장한 뒤 다운로드해 주세요.");const c=scope==="SELECTED"?[...S.selected]:null;if(scope==="SELECTED"&&!c.length)throw new Error("기업을 하나 이상 선택해 주세요.");const r=await api(`/api/runs/${S.run.run_id}/exports`,{method:"POST",body:JSON.stringify({scope,format,selected_ciks:c})}),a=document.createElement("a");a.href=r.download_url;a.download="";document.body.append(a);a.click();a.remove();toast("결과 다운로드를 시작했습니다.")}
function normalizeMetric(x){if(x.category!=="LEGACY_REPORTED")return x;const category=({revenue:"GROWTH",operating_income:"PROFITABILITY",net_income:"PROFITABILITY",cfo:"CASH_FLOW"})[x.metric_id]||"OTHER_REPORTED";return{...x,category}}
async function loadCatalog(id,token){let catalog;try{catalog=(await api(`/api/metric-catalog?dataset_id=${encodeURIComponent(id)}`)).map(normalizeMetric)}catch(e){catalog=[{metric_id:"revenue",label:"매출",category:"GROWTH",unit_kind:"MONEY",unit:"USD",definition_version:"annual-core-reported-v1",period_class:"FY",coverage:{}},{metric_id:"operating_income",label:"영업이익",category:"PROFITABILITY",unit_kind:"MONEY",unit:"USD",definition_version:"annual-core-reported-v1",period_class:"FY",coverage:{}},{metric_id:"net_income",label:"순이익",category:"PROFITABILITY",unit_kind:"MONEY",unit:"USD",definition_version:"annual-core-reported-v1",period_class:"FY",coverage:{}},{metric_id:"cfo",label:"영업활동 현금흐름",category:"CASH_FLOW",unit_kind:"MONEY",unit:"USD",definition_version:"annual-core-reported-v1",period_class:"FY",coverage:{}}]}if(token===S.contextToken)S.catalog=catalog}
function renderCompanyOptions(){const q=$("#company-query").value.trim().toLowerCase();$("#company-select").innerHTML=S.companies.filter(x=>!q||`${(x.tickers||[]).join(" ")} ${x.name||""}`.toLowerCase().includes(q)).map(x=>`<option value="${x.cik}" ${S.companySelection.has(x.cik)?"selected":""}>${esc((x.tickers||[])[0]||"")} · ${esc(x.name||"")}</option>`).join("")}
function syncCompanySelection(){[...$("#company-select").options].forEach(x=>x.selected?S.companySelection.add(x.value):S.companySelection.delete(x.value))}
async function loadCompanies(id,token){const r=await api(`/api/metadata?dataset_id=${encodeURIComponent(id)}&prepared=true&limit=500`);if(token!==S.contextToken)return;S.companies=r.rows;renderCompanyOptions();const a=[...new Map(S.companies.filter(x=>x.sic_code).map(x=>[x.sic_code,x.sic_description||"분류명 없음"])).entries()].sort((x,y)=>x[1].localeCompare(y[1]));$("#industry-select").innerHTML=a.map(([c,l])=>`<option value="${c}">${esc(l)}</option>`).join("")}
async function loadInputContext(id){const token=++S.contextToken;await Promise.all([loadCatalog(id,token),loadCompanies(id,token)])}
function mountAdmin(){if(!S.admin)return;const s=document.createElement("section");s.className="history";s.innerHTML='<div class="section-head"><div><span class="step">ADMIN</span><h2>자료 관리 진단</h2><p>수집·분류 담당자용 기업 메타데이터 조회입니다.</p></div></div><div class="compare"><label>기업명·티커·CIK 검색<input id="admin-query" type="search"></label><label>준비 상태<select id="admin-prepared"><option value="">전체</option><option value="true">준비됨</option><option value="false">미준비</option></select></label><button id="admin-search" type="button" class="quiet">조회</button></div><div id="admin-results" class="diff">검색 조건을 입력하거나 전체를 조회하세요.</div>';$("main").append(s);$("#admin-search").onclick=async()=>{try{const q=$("#admin-query").value,p=$("#admin-prepared").value,u=`/api/metadata?dataset_id=${encodeURIComponent($("#dataset").value)}&query=${encodeURIComponent(q)}&offset=0&limit=50${p?`&prepared=${p}`:""}`,r=await api(u);$("#admin-results").innerHTML=r.rows.length?r.rows.map(x=>`<p><b>${esc((x.tickers||[]).join(", ")||x.name)}</b> · ${esc(x.name)} · CIK ${esc(x.cik)} · SIC ${esc(x.sic_code||"UNKNOWN_SIC")} · ${x.financial_prepared?"ACTUAL_PREPARED":"NOT_PREPARED"}</p>`).join(""):"검색 결과가 없습니다."}catch(e){fail(e)}}}
const CORE_SHORT_LABELS={revenue:"매출",revenue_yoy:"매출 성장률",operating_margin:"영업이익률",net_income:"순이익",cfo:"영업현금흐름",standardized_fcf:"표준화 FCF",current_ratio:"유동비율",liabilities_to_assets:"부채/자산"};
const EXPLORER_PRESETS={CORE:["revenue","revenue_yoy","operating_margin","net_income","cfo","standardized_fcf","current_ratio","liabilities_to_assets"],GROWTH_PROFIT:["revenue","revenue_yoy","operating_margin","net_income"],CASH_STABILITY:["cfo","standardized_fcf","current_ratio","liabilities_to_assets"]};
function showView(view,focus=false){S.view=view;$$('[data-task-view]').forEach(x=>x.hidden=x.dataset.taskView!==view);$$('[data-view]').forEach(x=>{const active=x.dataset.view===view;x.classList.toggle("active",active);if(active)x.setAttribute("aria-current","page");else x.removeAttribute("aria-current")});if(focus){const target=$(`#${({explorer:"explorer-title",library:"library-title",screening:"criteria-title",history:"history-title"})[view]}`);target?.setAttribute("tabindex","-1");target?.focus()}}
function annualExplorerMetric(id){const m=S.explorerCatalog?.metrics.find(x=>x.metric_id===id);if(!m)throw new Error(`탐색 지표 정의를 찾을 수 없습니다: ${id}`);return m}
function inclusiveEnd(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||""))return value||"—";const d=new Date(`${value}T00:00:00Z`);d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10)}
function explorerPeriod(row){const p=row.actual_period;if(!p)return"선택 연도 자료 없음";const end=inclusiveEnd(p.context_end_date||p.period_end);return p.period_start?`${p.period_start} ~ ${end}`:`기준일 ${end}`}
function explorerValue(o,m){if(!o||o.value===null||o.value===undefined){const reason=(o?.reason_labels||[])[0]||"선택 연도 자료 없음";return`<span class="missing" title="${esc(reason)}" aria-label="자료 없음: ${esc(reason)}">—</span>`}return numberMarkup(o.value,m)}
function annualUpdateExplorerSort(){const current=$("#explorer-sort").value,ids=EXPLORER_PRESETS[$("#explorer-preset").value]||EXPLORER_PRESETS.CORE;$("#explorer-sort").innerHTML='<option value="company">기업명</option>'+ids.map(id=>`<option value="${id}">${esc(explorerMetric(id).label)}</option>`).join("");if([...$("#explorer-sort").options].some(x=>x.value===current))$("#explorer-sort").value=current}
function renderAnnualExplorer(){const r=S.explorer,ids=EXPLORER_PRESETS[$("#explorer-preset").value]||EXPLORER_PRESETS.CORE;if(!r)return;updateExplorerSort();$("#explorer-count").textContent=`${r.rows.length}개 기업 · FY${r.selected_fiscal_year}`;$("#explorer-year-note").textContent=`선택 연도 자료 ${r.selected_year_company_count}/${r.company_count} · 없는 기업도 목록에 유지합니다.`;$("#explorer-head").innerHTML=`<tr><th><span class="sr-only">비교 선택</span></th><th>기업</th><th>공시 재무기간</th>${ids.map(id=>{const m=explorerMetric(id);return`<th title="${esc(m.label)}">${esc(CORE_SHORT_LABELS[id]||m.label)}<small>${esc(unitLabel(m))}</small></th>`}).join("")}</tr>`;$("#explorer-body").innerHTML=r.rows.length?r.rows.map((row,index)=>{const c=row.company;return`<tr><td><input type="checkbox" data-explorer-select="${index}" aria-label="${esc(c.ticker)} 비교 선택" ${S.explorerSelected.has(c.cik)?"checked":""}></td><td><button class="company" data-explorer-open="${index}"><strong>${esc(c.name||c.ticker)}</strong><small>${esc(c.ticker)}</small><small class="industry">${esc(c.industry||"업종 정보 없음")}</small></button></td><td class="actual-period">${esc(explorerPeriod(row))}</td>${ids.map(id=>`<td>${explorerValue(row.metrics[id],explorerMetric(id))}</td>`).join("")}</tr>`}).join(""):`<tr><td colspan="${3+ids.length}" class="empty">검색 결과가 없습니다.</td></tr>`;$$('[data-explorer-select]').forEach(x=>x.onchange=()=>{const c=r.rows[Number(x.dataset.explorerSelect)].company;x.checked?S.explorerSelected.add(c.cik):S.explorerSelected.delete(c.cik);updateCompareButton()});$$('[data-explorer-open]').forEach(x=>x.onclick=()=>openProfile(r.rows[Number(x.dataset.explorerOpen)].company.cik,x).catch(fail));updateCompareButton()}
